import threading
import time


class InsufficientFunds(Exception):
    pass


class BankAccount:
    """A legacy account. Its methods are intentionally not thread-safe."""

    def __init__(self, initial_balance=0, operation_delay=0.0):
        if initial_balance < 0:
            raise ValueError("initial_balance must be non-negative")
        self._balance = initial_balance
        self.operation_delay = operation_delay
        self.base_deposit_calls = 0
        self.base_withdraw_calls = 0

    def deposit(self, amount):
        if amount <= 0:
            raise ValueError("amount must be positive")
        current = self._balance
        time.sleep(self.operation_delay)
        self._balance = current + amount
        self.base_deposit_calls += 1

    def withdraw(self, amount):
        if amount <= 0:
            raise ValueError("amount must be positive")
        if self._balance < amount:
            raise InsufficientFunds("insufficient balance")
        current = self._balance
        time.sleep(self.operation_delay)
        self._balance = current - amount
        self.base_withdraw_calls += 1


